#include "checksum.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int64_t rolling_checksum(const int32_t *v, size_t n) {
  int32_t acc = 0;
  for (size_t i = 0; i < n; ++i) {
    acc += v[i] * (int32_t)(i + 1);
  }
  return acc;
}

uint32_t digest32(const int32_t *v, size_t n) {
  unsigned long long h = 2166136261ULL;
  for (size_t i = 0; i < n; ++i) {
    h = h ^ (unsigned long long)(uint32_t)v[i];
    h = h * 16777619ULL;
  }
  return (uint32_t)h;
}

long load_series(const char *path, int32_t **out) {
  FILE *f = fopen(path, "r");
  if (!f) {
    *out = NULL;
    return -1;
  }
  size_t cap = 8;
  int32_t *buf = malloc(cap * sizeof(int32_t));
  long count = 0;
  char line[256];
  while (fgets(line, sizeof(line), f)) {
    char *p = line;
    while (*p == ' ' || *p == '\t') ++p;
    if (*p == '\n' || *p == '#' || *p == '\0') continue;
    if (count < (long)cap) {
      buf[count] = atoi(p);
      count += 1;
    }
  }
  fclose(f);
  *out = buf;
  return count;
}

