/* checksum - prints one line per data file. Do not modify. */
#include "checksum.h"

#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>

static const char *FILES[] = {
    "data/small.txt", "data/large.txt", "data/crlf.txt",  "data/long.txt",
    "data/noeol.txt", "data/empty.txt", "data/bad.txt",    "data/toobig.txt",
};

int main(void) {
  for (size_t i = 0; i < sizeof(FILES) / sizeof(FILES[0]); ++i) {
    int32_t *v = NULL;
    long n = load_series(FILES[i], &v);
    if (n < 0) {
      printf("%s invalid\n", FILES[i]);
      if (v != NULL) printf("%s LEAKED A BUFFER ON THE FAILURE PATH\n", FILES[i]);
      continue;
    }
    printf("%s count=%ld checksum=%" PRId64 " digest=%08x\n", FILES[i], n,
           rolling_checksum(v, (size_t)n), digest32(v, (size_t)n));
    free(v);
  }
  return 0;
}

